# >>> CHOICES
_choice_command_name() {
    ps -eo comm= | sed -e 's/^[[:space:]]*//' -e 's/[[:space:]]*$//' -e '/^$/d'
}

_choice_format() {
    ps L 2>/dev/null | gawk 'NF { print $1 }'
}

_choice_group() {
    ps -eo group= | sed -e 's/^[[:space:]]*//' -e 's/[[:space:]]*$//' -e '/^$/d'
}

_choice_pid() {
    ps -eo pid=,comm= | gawk 'NF >= 2 {
        pid = $1
        sub(/^[[:space:]]*[^[:space:]]+[[:space:]]+/, "")
        print pid "\t" $0
    }'
}

_choice_ppid() {
    ps -eo ppid=,comm= | gawk 'NF >= 2 {
        pid = $1
        sub(/^[[:space:]]*[^[:space:]]+[[:space:]]+/, "")
        print pid "\t" $0
    }'
}

_choice_sid() {
    ps -eo sess=,comm= | gawk 'NF >= 2 {
        sid = $1
        sub(/^[[:space:]]*[^[:space:]]+[[:space:]]+/, "")
        print sid "\t" $0
    }'
}

_choice_sort() {
    local sign=
    case "${ARGC_CWORD:-}" in
        -*) sign=- ;;
        +*) sign=+ ;;
    esac
    _choice_format | sed "s/^/$sign/"
}

_choice_tty() {
    ps -eo tty= | sed -e 's/^[[:space:]]*//' -e 's/[[:space:]]*$//' -e '/^$/d' -e '/^?$/d'
}

_choice_user() {
    ps -eo user= | sed -e 's/^[[:space:]]*//' -e 's/[[:space:]]*$//' -e '/^$/d'
}
